import bpy
from mathutils import Vector
# Report bounding boxes of top-level furniture to verify floor contact & scale
for o in bpy.data.objects:
    if o.parent is None and o.type in ('EMPTY',):
        # gather all mesh descendants
        zs=[]; xs=[]; ys=[]
        for ch in o.children_recursive:
            if ch.type=='MESH':
                for c in ch.bound_box:
                    w=ch.matrix_world@Vector(c)
                    xs.append(w.x); ys.append(w.y); zs.append(w.z)
        if zs:
            print(f"{o.name:8s} x[{min(xs):.2f},{max(xs):.2f}] y[{min(ys):.2f},{max(ys):.2f}] z[{min(zs):.2f},{max(zs):.2f}]  size=({max(xs)-min(xs):.2f},{max(ys)-min(ys):.2f},{max(zs)-min(zs):.2f})")
# total vertex count
tot=sum(len(o.data.vertices) for o in bpy.data.objects if o.type=='MESH')
print("total verts:", tot)
